SECRET_APPEND = '\nAlphaFeed Key 仅允许由 `api-center/alphafeed/` 的固定工作流注入官方 `alphafeed==0.1.4` SDK；客户端不得提交或覆盖 Key，不开放任意 SDK 方法、WebSocket、交易或下单。Overture Maps、OECD 和 World Bank 均为无密钥只读数据源。\n'


def main() -> None:
    for relative, content in FILES.items():
        path = ROOT / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")

    for relative, old, new in REPLACEMENTS:
        path = ROOT / relative
        text = path.read_text(encoding="utf-8")
        count = text.count(old)
        if count != 1:
            raise RuntimeError(
                f"expected exactly one match in {relative}; found {count} for {old!r}"
            )
        path.write_text(text.replace(old, new, 1), encoding="utf-8")

    secret_path = ROOT / "api-center/SECRET_ISOLATION_POLICY.md"
    secret_text = secret_path.read_text(encoding="utf-8")
    if "AlphaFeed Key 仅允许" not in secret_text:
        secret_path.write_text(secret_text.rstrip() + "\n" + SECRET_APPEND, encoding="utf-8")

    print(json.dumps({
        "status": "PASS",
        "files_written": len(FILES),
        "replacements": len(REPLACEMENTS),
        "managed_provider_count_after": 28,
        "managed_operation_count_after": 329,
        "worldbank_connector_count": 9,
    }))


if __name__ == "__main__":
    main()
